import type { AppEnv } from './env';

/**
 * Tab icon (public/icons, generated by AlUmmahNow packages/app-icons). Stage and production share
 * one bundle, so the variant is picked per request: QA and local get a violet corner dot, stage pink.
 * Production has no SVG (null): browsers prefer an SVG over sized PNGs and blur its image.
 */
export function faviconSvgPath(appEnv: AppEnv): string | null {
  if (appEnv === 'production') return null;
  if (appEnv === 'stage') return '/icons/favicon-stage.svg';
  return '/icons/favicon-qa.svg';
}

export interface IconLink { href: string; type?: string; sizes?: string }

/** Exact-size PNGs, each its own downscale of the logo, so the browser never shrinks it itself. */
export const TAB_PNG_SIZES = [16, 32, 48, 96] as const;

/** rel="icon" links: the ICO, then the sized PNGs (production) or the dot SVG (QA, stage). */
export function tabIconLinks(appEnv: AppEnv): IconLink[] {
  const svg = faviconSvgPath(appEnv);
  return [
    { href: '/favicon.ico', sizes: '16x16 32x32 48x48' },
    ...(svg
      ? [{ href: svg, type: 'image/svg+xml' }]
      : TAB_PNG_SIZES.map((s) => ({ href: `/icons/favicon-${s}x${s}.png`, type: 'image/png', sizes: `${s}x${s}` }))),
  ];
}
